def forward(groups):
    date, time = groups[0], groups[1]
    dt = datetime.strptime(f'{date} {time}', '%Y-%m-%d %H:%M:%S,%f')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%Y-%m-%d %H:%M:%S,%f')[:-3]
